INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'en-US', 'name', 'Privacy Policy', 'reviewed', SHA2('隐私协议', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'en-US', 'value', '<h2>Privacy Policy</h2><p>Thank you for using this application. We value and protect your personal information and process it only as necessary to provide account login, application features, and customer service.</p><h3>I. Use of Information</h3><p>We use your information in accordance with applicable laws and this policy, and will not use it for unrelated purposes.</p><h3>II. Your Rights</h3><p>You may access, correct, or delete your personal information in accordance with the law, or contact us through the channels published in the application.</p>', 'reviewed', SHA2('<h2>隐私政策</h2><p>感谢您使用本应用。我们重视并保护您的个人信息，仅在提供账号登录、应用功能和客户服务所必需的范围内处理相关信息。</p><h3>一、信息使用</h3><p>我们会按照法律法规和本协议约定使用您的信息，不会将其用于无关目的。</p><h3>二、您的权利</h3><p>您可以依法查询、更正、删除个人信息，或通过应用内公布的渠道联系我们。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'en-US', 'name', 'Terms of Service', 'reviewed', SHA2('服务条款', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'en-US', 'value', '<h2>Terms of Service</h2><p>Welcome to this application. Please read and understand this agreement and the related rules before using the application. By using the application services, you agree to comply with them.</p><h3>I. Service Use</h3><p>Please use each feature lawfully and in accordance with the instructions on the page. You must not use this application for illegal activities or activities that infringe on the rights of others.</p><h3>II. Changes to the Agreement</h3><p>We may update this agreement according to changes in business and laws and regulations, and will display the updated version in the application.</p>', 'reviewed', SHA2('<h2>服务条款</h2><p>欢迎使用本应用。使用本应用前，请您阅读并理解本协议。您开始使用应用服务，即表示同意遵守本协议及相关规则。</p><h3>一、服务使用</h3><p>请您依法、合规并按照页面提示使用各项功能，不得利用本应用从事违法或损害他人权益的活动。</p><h3>二、协议变更</h3><p>我们会根据业务和法律法规变化更新本协议，并在应用内向您展示更新后的内容。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
